provisioner "local-exec" {
  command = "echo done"
}

resource "aws_instance" "web" {
  provisioner "local-exec" {
    command = "echo ${self.public_ip} >> inventory.txt"
  }
}

provisioner "local-exec" {
  command    = "curl -f https://example.com/notify"
  on_failure = "continue"
}

provisioner "local-exec" {
  command     = "Write-Output done"
  interpreter = ["PowerShell", "-Command"]
}
